INSERT INTO public.assessment_questions (framework, section_id, section_name, subsection, question_number, question, why_matters, regulatory_ref, risk, evidence_req, remediation, uid) VALUES
('popia', 6, 'Direct Marketing - Section 69', 'Opt-In Requirements', 1, 'Does the organisation obtain opt-in consent before sending electronic direct marketing communications?', 'Section 69 requires opt-in consent for electronic direct marketing communications.', 'POPIA Section 69 direct marketing; Electronic Communications and Transactions Act 25 of 2020; Information Regulator direct marketing guidance', 'Critical', 'Opt-in consent procedures; consent records; consent withdrawal mechanisms; opt-in database; consent audit trail.', 'Implement opt-in consent procedures for electronic marketing. Maintain consent database and audit trail. Provide easy withdrawal mechanisms.', 'P6_DM_1'),
('popia', 6, 'Direct Marketing - Section 69', 'Opt-In Requirements', 2, 'Is consent obtained using the prescribed Form 4 format?', 'Section 69 specifies that consent must be obtained using the prescribed Form 4 format.', 'POPIA Section 69 direct marketing; Information Regulator Form 4 template; Electronic Communications and Transactions Act', 'Critical', 'Form 4 template usage; consent form examples; Form 4 completion records; legal review of consent forms.', 'Use Information Regulator Form 4 template for consent requests. Maintain records of Form 4 completion. Obtain legal review of consent forms.', 'P6_DM_2'),
('popia', 6, 'Direct Marketing - Section 69', 'Opt-In Requirements', 3, 'Is consent obtained as a once-off ask rather than bundled consent?', 'Section 69 requires consent to be obtained as a once-off ask, not bundled with other consent.', 'POPIA Section 69 direct marketing; Information Regulator direct marketing guidance; Electronic Communications and Transactions Act', 'Critical', 'Consent procedure documentation; consent flow records; user experience testing; consent separation evidence.', 'Implement once-off consent ask procedures. Document consent flow and ensure separation from other consents.', 'P6_DM_3'),
('popia', 6, 'Direct Marketing - Section 69', 'Opt-In Requirements', 4, 'Are consent records retained for at least 3 years post-relationship termination?', 'Section 69 requires consent records to be retained for at least 3 years after the relationship ends.', 'POPIA Section 69 direct marketing; Information Regulator direct marketing guidance; Electronic Communications and Transactions Act', 'High', 'Consent database retention policy; data retention procedures; backup and recovery for consent records; deletion scheduling.', 'Implement 3-year consent retention policy. Establish data retention procedures for consent database.', 'P6_DM_4'),
('popia', 6, 'Direct Marketing - Section 69', 'Existing Customer Exception', 5, 'Does the organisation apply the existing customer exception appropriately?', 'Section 69 provides an exception for existing customers where the organisation has an ongoing business relationship.', 'POPIA Section 69 direct marketing; Information Regulator direct marketing guidance; Electronic Communications and Transactions Act', 'High', 'Existing customer identification; relationship documentation; exception application procedures; consent records for existing customers.', 'Develop existing customer identification procedures. Document ongoing relationships. Apply exception appropriately and maintain records.', 'P6_DM_5'),
('popia', 6, 'Direct Marketing - Section 69', 'Opt-Out Mechanisms', 6, 'Are opt-out mechanisms provided for non-electronic direct marketing?', 'Section 69 requires opt-out mechanisms for non-electronic direct marketing (post, in-person).', 'POPIA Section 69 direct marketing; Information Regulator direct marketing guidance; Electronic Communications and Transactions Act', 'High', 'Opt-out procedures for non-electronic marketing; opt-out database; communication of opt-out rights; opt-out processing procedures.', 'Implement opt-out mechanisms for non-electronic marketing. Maintain opt-out database. Communicate opt-out rights clearly.', 'P6_DM_6'),
('popia', 6, 'Direct Marketing - Section 69', 'Opt-Out Mechanisms', 7, 'Are opt-out requests processed promptly and effectively?', 'Section 69 requires organisations to respect opt-out requests promptly and effectively.', 'POPIA Section 69 direct marketing; Information Regulator direct marketing guidance; Electronic Communications and Transactions Act', 'High', 'Opt-out processing procedures; response time tracking; opt-out database updates; user feedback on opt-out process.', 'Implement prompt opt-out processing procedures. Track response times and update opt-out databases. Monitor user feedback.', 'P6_DM_7'),
('popia', 6, 'Direct Marketing - Section 69', 'Phone Call Marketing', 8, 'Are phone call marketing activities treated as electronic communications requiring opt-in?', 'The Information Regulator has interpreted phone call marketing as electronic communications requiring opt-in consent.', 'POPIA Section 69 direct marketing; Information Regulator direct marketing guidance; Electronic Communications and Transactions Act', 'Critical', 'Phone call marketing procedures; opt-in procedures for phone calls; call recording for consent; staff training on phone consent.', 'Treat phone call marketing as electronic communications. Implement opt-in procedures for phone calls. Record calls for consent verification.', 'P6_DM_8'),
('popia', 6, 'Direct Marketing - Section 69', 'Marketing Database Management', 9, 'Is the direct marketing database maintained with current opt-in status?', 'A well-maintained marketing database is essential for ensuring compliance with opt-in requirements.', 'POPIA Section 69 direct marketing; Information Regulator direct marketing guidance; Electronic Communications and Transactions Act', 'High', 'Marketing database procedures; opt-in status tracking; database update procedures; data quality controls; audit trails.', 'Implement marketing database with opt-in status tracking. Establish regular update procedures. Maintain data quality controls and audit trails.', 'P6_DM_9'),
('popia', 6, 'Direct Marketing - Section 69', 'Marketing Database Management', 10, 'Are opt-out requests processed across all marketing channels?', 'Opt-out requests must be honoured across all marketing channels to ensure full compliance.', 'POPIA Section 69 direct marketing; Information Regulator direct marketing guidance; Electronic Communications and Transactions Act', 'High', 'Cross-channel opt-out procedures; channel integration for opt-out processing; opt-out database sync; testing of opt-out across channels.', 'Implement cross-channel opt-out processing. Ensure opt-out database syncs across all marketing channels. Test opt-out effectiveness.', 'P6_DM_10'),
('popia', 6, 'Direct Marketing - Section 69', 'Frequency and Timing', 11, 'Are there controls on the frequency and timing of direct marketing communications?', 'While POPIA doesn''t specify frequency limits, excessive or intrusive marketing can violate other provisions and damage reputation.', 'POPIA Section 69 direct marketing; Information Regulator direct marketing guidance; Electronic Communications and Transactions Act; Code of Conduct for Direct Marketing', 'Medium', 'Marketing communication frequency guidelines; timing restrictions; user feedback on frequency; unsubscribe rate monitoring; communication preference management.', 'Develop frequency and timing guidelines for marketing communications. Monitor user feedback and unsubscribe rates. Allow communication preference management.', 'P6_DM_11'),
('popia', 6, 'Direct Marketing - Section 69', 'Do Not Contact Lists', 12, 'Does the organisation respect Do Not Contact lists and suppressor lists?', 'Respecting Do Not Contact lists is essential for compliance and good practice.', 'PAIA Do Not Contact requirements; Information Regulator direct marketing guidance; Electronic Communications and Transactions Act; Direct Marketing Association lists', 'Medium', 'Do Not Contact list subscription procedures; list integration with marketing systems; list update processes; compliance verification against lists.', 'Subscribe to relevant Do Not Contact lists. Integrate lists with marketing systems. Regularly update list subscriptions and verify compliance.', 'P6_DM_12');